import{_ as e,c as t,a2 as o,o as r}from"./chunks/framework.Dz7_3PEu.js";const s="/assets/image-20240529165830856.DUMAx_E9.png",n="/assets/image-20240529170729259.DRKCEBnK.png",i="/assets/image-20240529171618951.x95hEjok.png",b=JSON.parse('{"title":"晶格链区块与合约验证","description":"","frontmatter":{},"headers":[],"relativePath":"source/consensus/blockVerify/blockVerify.md","filePath":"source/consensus/blockVerify/blockVerify.md","lastUpdated":1736756758000}'),l={name:"source/consensus/blockVerify/blockVerify.md"};function p(c,a,h,d,f,u){return r(),t("div",null,a[0]||(a[0]=[o('<h1 id="晶格链区块与合约验证" tabindex="-1">晶格链区块与合约验证 <a class="header-anchor" href="#晶格链区块与合约验证" aria-label="Permalink to &quot;晶格链区块与合约验证&quot;">​</a></h1><h2 id="_1-合约验证目的" tabindex="-1">1.合约验证目的 <a class="header-anchor" href="#_1-合约验证目的" aria-label="Permalink to &quot;1.合约验证目的&quot;">​</a></h2><p>晶格链支持多语言智能合约，但对这类智能合约的逻辑约束力不强，如过在合约中存在下面情况的逻辑就会导致账本不一致</p><blockquote><ol><li>合约的执行结果因节点而异。不同节点执行合约后产生的结果不一样</li><li>合约的执行结果因时而异。</li><li>合约执行结果随机。</li></ol></blockquote><h2 id="_2-如何验证合约" tabindex="-1">2.如何验证合约 <a class="header-anchor" href="#_2-如何验证合约" aria-label="Permalink to &quot;2.如何验证合约&quot;">​</a></h2><h3 id="_2-1-验证守护区块" tabindex="-1">2.1. 验证守护区块 <a class="header-anchor" href="#_2-1-验证守护区块" aria-label="Permalink to &quot;2.1. 验证守护区块&quot;">​</a></h3><p><img src="'+s+'" alt="image-20240529165830856"></p><p>上图的流程时晶格链一直使用的<code>守护区块验证过程</code> , 通过这个过程可以判断合约是否存在错误。</p><h3 id="_2-2-通过写集定位错误的合约" tabindex="-1">2.2 通过写集定位错误的合约 <a class="header-anchor" href="#_2-2-通过写集定位错误的合约" aria-label="Permalink to &quot;2.2 通过写集定位错误的合约&quot;">​</a></h3><p>通过2.1的步骤只能对区块是否包含错误的合约做出判断，但不能确定具体是哪个合约出错了。</p><p>为每一笔多语言智能合约交易生成写集。节点通过<strong>对比自己执行合约生成的写集与收到的写集 hash是否一致</strong>，判断合约是否存在错误。</p><p><img src="'+n+'" alt="image-20240529170729259"></p><h3 id="_2-3-写集的结构" tabindex="-1">2.3 写集的结构 <a class="header-anchor" href="#_2-3-写集的结构" aria-label="Permalink to &quot;2.3  写集的结构&quot;">​</a></h3><p><img src="'+i+'" alt="image-20240529171618951"></p><h2 id="_3-如何对区块的正确性下定论" tabindex="-1">3. 如何对区块的正确性下定论 <a class="header-anchor" href="#_3-如何对区块的正确性下定论" aria-label="Permalink to &quot;3. 如何对区块的正确性下定论&quot;">​</a></h2><p>活跃性</p><p>活跃性是系统继续运行时在分布式系统环境中使用的术语。这意味着<strong>即使出现一些错误，系统也不会停止运行</strong>。在区块链的情况下，活跃意味着系统将继续向链中添加新的区块，并且<strong>在任何时候系统都不会停止工作</strong>。</p><p>安全性</p><p>当系统收敛于单个决策时，安全性是分布式系统环境中使用的术语。在分布式系统中，节点可能会分成两个决策或进一步拆分，分布式系统的安全性<strong>确保了即使存在故障节点，网络也会在所有可靠节点上以单个决策结束</strong>。</p><h3 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h3><p>miner收到f+1个签名（正确/错误）即认为区块正确/错误。</p><h3 id="证明" tabindex="-1">证明 <a class="header-anchor" href="#证明" aria-label="Permalink to &quot;证明&quot;">​</a></h3><p>证明：共识要保证系统的<strong>活跃性</strong>和<strong>安全性</strong>，将从这两方面证明区块验证的可行性。</p><p>假设目前使用的为BFT类共识，容错能力为3f+1=N。</p><p>节点类型分为3种正确的节点（correct), 错误的节点（fault）,未知的节点（Unreachable）。</p><h4 id="_3-1-活跃性证明" tabindex="-1">3.1 活跃性证明 <a class="header-anchor" href="#_3-1-活跃性证明" aria-label="Permalink to &quot;3.1 活跃性证明&quot;">​</a></h4><p>保证在有f个错误节点和f个未知节点，不影响共识。</p><p>正确节点的数量为 C &gt;= N -2f 即 C &gt;= f+1</p><h4 id="_3-2-安全性证明" tabindex="-1">3.2 安全性证明 <a class="header-anchor" href="#_3-2-安全性证明" aria-label="Permalink to &quot;3.2 安全性证明&quot;">​</a></h4><p>不同的决策下能够决策出一致性决定。</p><p>反正法：假设存在情况Q，造成节点做出了不一致决策</p><blockquote><p>有两个不同的决定 A 和 B，其中A认为区块正确。</p><p>A: f + 1</p><p>B: 2f (f&gt;=1)</p></blockquote><p>在假设只有f个fault节点时，<strong>Q是不可能出现的</strong>，因为如果正确的节点认为A正确，那B的签名最多有f个。</p><p>因此只需要收到f+1个<strong>同类型</strong>的签名即可断定该签名至少包含1个正确节点的签名, 就可以断定该区块是正确/错误的。</p><p>在<strong>合约内容存在错误</strong>的情况下，两个正确的节点也有可能因为合约的错误而产生不同的结论，因此是有可能出现上述情况的。此时A与B都包含了正确节点的签名，miner通过时间判断哪个决定的签名首先被收集足够，即确定该结论，<strong>不会出现决策不一致</strong>。</p>',35)]))}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
